css:
[data-bz-node="tiles"]{padding:0 calc(29 * var(--u));height:calc(295 * var(--u));overflow:hidden}
[data-bz-node="tiles-row"]{gap:5px}
[data-bz-node="tiles"] img{display:block;width:100%;height:calc(295 * var(--u));object-fit:cover;border-radius:0}
[data-bz-node="tiles"] .bz-block,[data-bz-node="tiles"] figure{margin:0}
[data-bz-node="tiles"] img{transition:filter .35s ease}
[data-bz-node="tiles"] a:hover img,[data-bz-node="tiles"] a:focus-visible img{filter:brightness(1.75) saturate(1.1)}
@media (prefers-reduced-motion:reduce){[data-bz-node="tiles"] img{transition:none}}
